from taf.sw.nadcm.httpclient.ApiClient import ApiClient
from taf.sw.nadcm.httpclient.nadcm_uri import InventoryURI


class InventoryV1(object):
    def __init__(self, configuration, access_token):
        self.api_client = ApiClient(configuration, access_token)

    def get_inventory_nodes(self, timeout=60):
        uri = InventoryURI().inventory_nodes_uri
        return self.api_client.send_get_request(uri=uri, timeout=timeout)

    def get_node_credentials(self, node_id, timeout=60):
        uri = InventoryURI().credential_for_node_uri + "/" + node_id
        return self.api_client.send_get_request(uri=uri, timeout=timeout)

    def change_node_management_credential(self, node_id, user, password, timeout=60):
        node_credential = self.get_node_credentials(node_id=node_id, timeout=timeout)
        node_credential['user'] = user
        node_credential['pass'] = password
        return self.set_device_access_credentials(node_id=node_id, timeout=timeout, **node_credential)

    def change_redfish_credential(self, node_id, user, password, timeout=60):
        node_credential = self.get_node_credentials(node_id=node_id, timeout=timeout)
        node_credential['redfish']['user'] = user
        node_credential['redfish']['pass'] = password
        return self.set_device_access_credentials(node_id=node_id, timeout=timeout, **node_credential)

    def set_device_access_credentials(self, node_id, timeout=60, **kwargs):
        uri = InventoryURI().credential_for_node_uri + "/" + node_id
        return self.api_client.send_post_request(uri=uri, json=kwargs, timeout=timeout)

    def update_device_access_credentials(self, node_id, timeout=60, **kwargs):
        node_credential = self.get_node_credentials(node_id=node_id, timeout=timeout)
        data = self._prepare_credential_data(existing_data=node_credential, **kwargs)
        return self.set_device_access_credentials(node_id=node_id, timeout=timeout, **data)

    def upload_a_file(self, file_name, data, timeout=60):
        uri = InventoryURI().inventory_files_uri + "?name=" + file_name
        result = self.api_client.send_post_request(uri=uri, data=data, timeout=timeout)
        return result

    def add_file_metadata_by_id(self, file_id, file_type, hw_profiles=[], release_id="", timeout=60):
        data = [{"op": "replace", "path": "/upgrade_file_type", "value": file_type},
                {"op": "replace", "path": "/upgrade_product_names", "value": hw_profiles},
                {"op": "replace", "path": "/release_ids", "value": release_id}]
        uri = InventoryURI().inventory_file_id_uri + "/" + file_id
        return self.api_client.send_patch_request(uri=uri, json=data, timeout=timeout)

    def delete_file_by_id(self, file_id, timeout=60):
        uri = InventoryURI().inventory_file_id_uri + "/" + file_id
        return self.api_client.send_delete_request(uri=uri, timeout=timeout)

    def list_files(self, field, value, timeout=60):
        uri = InventoryURI().inventory_files_uri + f"?field={field}&value={value}"
        return self.api_client.send_get_request(uri=uri, timeout=timeout)

    def device_query(self, timeout=60, **kwargs):
        uri = InventoryURI().inventory_devices_uri
        if kwargs:
            parameters = []
            parameters = [f"{key}={value}" for key, value in kwargs.items() if value]
            uri = uri + '?' + '&'.join(parameters)
        result = self.api_client.send_get_request(uri=uri, timeout=timeout)
        return result

    def _ip_type(self, ip):
        return "6" if ":" in ip else ""

    def get_node_info_by_device_ip(self, device_ip, select=[], timeout=60):
        ip_type = self._ip_type(device_ip)
        select = ','.join(select) if select else select
        get_filter = f"eq(obm_ip{ip_type},%27{device_ip}%27)"
        result = self.device_query(select=select, filter=get_filter, timeout=timeout)
        if not result.get('data', None):
            raise ValueError("Device {} does not exist in NADCM!".format(device_ip))
        return result['data'][0]

    def get_default_credentials(self, timeout=60):
        uri = InventoryURI().credential_defaults_uri
        return self.api_client.send_get_request(uri=uri, timeout=timeout)

    def get_default_credential_by_type(self, deftype, timeout=60):
        uri = InventoryURI().credential_defaults_uri + "/type/" + deftype
        return self.api_client.send_get_request(uri=uri, timeout=timeout)

    def _prepare_credential_data(self, existing_data=None, **kwargs):
        data = existing_data if existing_data else {}
        for key, value in kwargs.items():
            keys = key.split('_')
            if len(keys) == 2:
                path_key, item_key = keys
                data.setdefault(path_key, {})[item_key] = value
            else:
                key = "pass" if key == "password" else key
                data[key] = value
        return data

    def create_default_credentials(self, deftype, timeout=60, **kwargs):
        data = {"deftype": deftype}
        data = self._prepare_credential_data(existing_data=data, **kwargs)
        uri = InventoryURI().credential_defaults_uri
        return self.api_client.send_post_request(uri=uri, json=[data], timeout=timeout)

    def update_default_credentials(self, deftype, timeout=60, **kwargs):
        existing_data = self.get_default_credential_by_type(deftype)
        data = self._prepare_credential_data(existing_data=existing_data, **kwargs)
        uri = InventoryURI().credential_defaults_uri + "/type/" + deftype
        return self.api_client.send_put_request(uri=uri, json=data, timeout=timeout)

    def delete_default_credentials(self, deftype, timeout=60):
        uri = InventoryURI().credential_defaults_uri + "/type/" + deftype
        return self.api_client.send_delete_request(uri=uri, timeout=timeout)

    def update_device_data(self, node_id, operation, data_path, value, timeout=60):
        data = [{"op": operation, "path": data_path, "value": value}]
        uri = InventoryURI().inventory_nodes_id_uri + node_id
        return self.api_client.send_patch_request(uri=uri, json=data, timeout=timeout)

    def create_device(self, timeout=60, **kwargs):
        uri = InventoryURI().inventory_nodes_uri
        return self.api_client.send_post_request(uri=uri, json=kwargs, timeout=timeout)

    def delete_node(self, node_id, timeout=60):
        uri = InventoryURI().inventory_nodes_id_uri + "/" + node_id
        return self.api_client.send_delete_request(uri, timeout=timeout)

